module hdmi_mixer #(
    parameter H_OFFSET = 128,
    parameter V_OFFSET = 60,
    parameter IMG_WIDTH = 1920,
    parameter IMG_HEIGHT = 1080,
    parameter integer DEBUG_MODE = 0,
    parameter integer GAMMA_ENABLE = 1
)(
    input [16:0] I_speed_payload,input I_speed_request,output O_speed_ack,
    input [171:0] I_roi_payload,input I_roi_request,output O_roi_ack,
    input [171:0] I_sticker_payload,input I_sticker_request,output O_sticker_ack,
    input wire        I_clk,
    input wire        I_rst_n,

    input wire        I_video_vsync,
    input wire        I_video_hsync,
    input wire        I_video_de,
    input wire        I_video_user,
    input wire        I_video_last,

    input wire[3:0]   I_debug_status,
    input wire[3:0]   I_switch_mode,
    output wire[3:0]  O_filter_mode,
    output wire signed [12:0] O_pen_exposure_offset,
    output wire O_pen_exposure_begin,O_pen_exposure_toggle,
    input wire I_pen_exposure_ack,
    input wire[6:0] I_pen_gain,
    output wire       O_pen_capture_toggle,
    output wire       O_pen_view_toggle,O_pen_view_target,
    input wire[1:0]   I_snapshot_status,
    input wire I_snapshot_capture_event,
    output wire[127:0] O_photo_stickers,
    input wire        I_auth_valid,I_auth_event,I_auth_variant,
    input wire[1:0]   I_auth_status,
    input wire        I_detect_valid,
    input wire[2:0]   I_detect_color,
    input wire[11:0]  I_detect_left,
    input wire[11:0]  I_detect_right,
    input wire[11:0]  I_detect_top,
    input wire[11:0]  I_detect_bottom,
    input wire[29:0]  I_detect_history, // legacy compatibility, no longer displayed
    input wire [31:0] I_latency_now_gray,I_latency_stamp,
    input wire I_latency_valid,

    output wire       O_video_rd_en,
    input wire[23:0]  I_video_rd_data,

    output reg        O_hdmi_vsync,
    output reg        O_hdmi_hsync,
    output reg        O_hdmi_de,
    output reg[23:0]  O_hdmi_data
);

    // Raster counters follow the SAME two-cycle delay as base video data.
    reg [1:0] S_frog_user_pipe,S_frog_last_pipe;
    reg [11:0] S_frog_scan_x,S_frog_scan_y;
    wire [11:0] S_frog_x=S_frog_scan_x;
    wire [11:0] S_frog_y=S_frog_scan_y;
    reg S_base_vsync,S_base_hsync,S_base_de;
    reg [23:0] S_base_data;
    reg[23:0]S_base_no_ui;
    reg S_prebase_vsync,S_prebase_hsync,S_prebase_de,S_ui_de_q;
    reg S_osd_red_delay,S_osd_blue_delay,S_sticker_ui_delay,S_frog_alpha_delay;
    reg[23:0]S_sticker_pixel_delay,S_frog_pixel_delay;

    wire S_frog_alpha,S_frog_active;
    wire [23:0] S_frog_pixel;
    wire [11:0] S_frog_left,S_frog_top,S_frog_width,S_frog_height;
    wire [2:0] S_blue_state;
    wire [1:0] S_blue_selection,S_blue_size;
    wire [6:0] S_blue_progress;
    wire S_blue_visible;
    wire [11:0] S_blue_anchor_x,S_blue_anchor_y;
    reg        S_video_vsync_1d;
    reg        S_video_vsync_2d;
    reg        S_video_hsync_1d;
    reg        S_video_hsync_2d;
    reg        S_video_de_1d;
    reg        S_video_de_2d;
    reg [23:0] S_video_data_1d;
    wire [23:0] S_video_data_2d;
    generate if(GAMMA_ENABLE!=0 && DEBUG_MODE==0)begin:shared_gamma_rom
      photo_gamma_rom rg(.clk(I_clk),.en(I_rst_n),.a(S_video_data_1d[23:16]),.b(S_video_data_1d[15:8]),
        .qa(S_video_data_2d[23:16]),.qb(S_video_data_2d[15:8]));
      photo_gamma_rom blue(.clk(I_clk),.en(I_rst_n),.a(S_video_data_1d[7:0]),.b(8'd0),
        .qa(S_video_data_2d[7:0]),.qb());
    end else begin:gamma_bypass
      reg[23:0]data;
      always @(posedge I_clk)if(I_rst_n)data<=S_video_data_1d;
      assign S_video_data_2d=data;
    end endgenerate
    reg [11:0] S_x;
    reg [11:0] S_y;
    reg        S_detect_valid;
    reg [2:0]  S_detect_color;
    reg [11:0] S_detect_left;
    reg [11:0] S_detect_right;
    reg [11:0] S_detect_top;
    reg [11:0] S_detect_bottom;
    // Display-only hold registers. Gesture control continues to use the live
    // detector, while the visible box survives the dark half-cycle.
    reg        S_display_box_valid;
    reg [2:0]  S_display_color;
    reg        S_display_variant;
    reg [11:0] S_display_left,S_display_right,S_display_top,S_display_bottom;

    reg S_auth_valid,S_auth_event,S_auth_seen,S_auth_variant;
    reg [1:0] S_auth_status;
    wire S_auth_enter=(S_auth_event!=S_auth_seen) && S_auth_valid;
    always @(posedge I_clk or negedge I_rst_n) begin
        if(!I_rst_n) S_auth_seen<=0;
        else if(I_video_user) S_auth_seen<=S_auth_event;
    end
    wire [1:0] S_pen_state;
    wire [6:0] S_pen_progress;
    wire [3:0] S_pen_selection;
    reg [1:0] S_photo_status_meta,S_photo_status_sync;
    always @(posedge I_clk or negedge I_rst_n) begin
        if(!I_rst_n) begin S_photo_status_meta<=0;S_photo_status_sync<=0;end
        else begin S_photo_status_meta<=I_snapshot_status;S_photo_status_sync<=S_photo_status_meta;end
    end
    wire [1:0] S_photo_selection,S_photo_result;
    wire [2:0] S_photo_state;
    wire [6:0] S_photo_progress;
    wire [1:0] S_photo_seconds;
    wire [11:0] S_pen_anchor_x,S_pen_anchor_y;
    wire S_pen_green,S_menu_overlay;
    wire legacy_overlay,roi_overlay;wire [23:0] legacy_pixel,roi_pixel;
    wire [6:0] S_pen_move_distance;
    wire [23:0] S_menu_pixel;
    wire [11:0] S_latency_bcd;
    wire S_latency_show;
    wire [16:0] S_speed_frame;
    led_speed_mailbox_rx u_speed_rx(.clk(I_clk),.rst_n(I_rst_n),.tick(I_video_user),
      .payload(I_speed_payload),.request(I_speed_request),.ack(O_speed_ack),.value(S_speed_frame));
    frame_latency_display u_latency_display(.clk(I_clk),.rst_n(I_rst_n),.tick(I_video_user),
      .now_gray(I_latency_now_gray),.stamp(I_latency_stamp),.valid(I_latency_valid),
      .photo(S_photo_status_sync[1]),.bcd(S_latency_bcd),.show(S_latency_show));
    reg [6:0] S_gain_meta,S_gain_sync,S_gain_settled;
    reg [3:0] S_gain_hundreds,S_gain_tens,S_gain_ones;
    wire [6:0] S_gain_below_100=S_gain_settled>=100 ?
                                 S_gain_settled-7'd100:S_gain_settled;
    wire [3:0] S_gain_tens_calc=S_gain_below_100>=90 ? 9:
                                S_gain_below_100>=80 ? 8:
                                S_gain_below_100>=70 ? 7:
                                S_gain_below_100>=60 ? 6:
                                S_gain_below_100>=50 ? 5:
                                S_gain_below_100>=40 ? 4:
                                S_gain_below_100>=30 ? 3:
                                S_gain_below_100>=20 ? 2:
                                S_gain_below_100>=10 ? 1:0;
    wire [6:0] S_gain_tens_x10=({3'd0,S_gain_tens_calc}<<3)+
                                ({3'd0,S_gain_tens_calc}<<1);
    assign O_filter_mode=I_switch_mode;
    assign O_pen_exposure_offset=0;assign O_pen_exposure_begin=0;assign O_pen_exposure_toggle=0;
    assign S_pen_state=0;assign S_pen_progress=0;assign S_pen_selection=0;
    assign S_pen_anchor_x=0;assign S_pen_anchor_y=0;assign S_pen_green=0;assign S_pen_move_distance=0;
    // Album lifetime follows the actual camera-domain grant, whose loss rule
    // is 20 camera frames. Coordinate-bus settling misses are not auth loss.
    (* ASYNC_REG="TRUE" *) reg [1:0] S_photo_auth_sync;
    always @(posedge I_clk or negedge I_rst_n) begin
        if(!I_rst_n) S_photo_auth_sync<=0;
        else S_photo_auth_sync<={S_photo_auth_sync[0],I_auth_valid};
    end
    red_pen_capture u_red_pen_capture(
        .clk(I_clk),.rst_n(I_rst_n),.tick(I_video_user),.enable(1'b1),.auth_enter(S_auth_enter),.auth_valid(S_photo_auth_sync[1]),
        .detected(S_detect_valid && S_auth_valid),.color(S_detect_color),
        .variant(S_auth_variant),
        .left(S_detect_left),.right(S_detect_right),.top(S_detect_top),.bottom(S_detect_bottom),
        .state(S_photo_state),.progress(S_photo_progress),.seconds_left(S_photo_seconds),
        .capture_toggle(O_pen_capture_toggle),.snapshot_valid(S_photo_status_sync[0]),
        .snapshot_view(S_photo_status_sync[1]),.result_code(S_photo_result),
        .view_toggle(O_pen_view_toggle),.view_target(O_pen_view_target),.selection(S_photo_selection)
    );
    wire [171:0] sticker_config;
    // Freeze only the four object descriptors. Reuse the same textures and
    // renderer for playback; photo pixels (including ISP filters) stay in DDR.
    reg [127:0] photo_stickers;
    assign O_photo_stickers=photo_stickers;
    (* ASYNC_REG="TRUE" *) reg [2:0] capture_event_sync;
    reg capture_event_seen,photo_view_frame;
    reg [3:0] shutter_pipe;
    reg [1:0] flash_frames;
    wire capture_changed=capture_event_sync[2]!=capture_event_seen;
    wire shutter_for_input=I_video_user ? (capture_changed || flash_frames>1):flash_frames!=0;
    wire [171:0] render_config={44'd0,photo_view_frame ? photo_stickers:sticker_config[127:0]};
    always @(posedge I_clk or negedge I_rst_n) begin
        if(!I_rst_n) begin
            photo_stickers<=0;capture_event_sync<=0;capture_event_seen<=0;
            photo_view_frame<=0;shutter_pipe<=0;flash_frames<=0;
        end else begin
            capture_event_sync<={capture_event_sync[1:0],I_snapshot_capture_event};
            shutter_pipe<={shutter_pipe[2:0],shutter_for_input};
            // Commit at SOF: snapshot the layout of the frame just displayed.
            // Both the saved layout and flash are coherent for an entire frame.
            if(I_video_user) begin
                photo_view_frame<=S_photo_status_sync[1];
                if(capture_changed) begin
                    capture_event_seen<=capture_event_sync[2];
                    photo_stickers<=sticker_config[127:0];
                    flash_frames<=2;
                end else if(flash_frames!=0) flash_frames<=flash_frames-1'b1;
            end
        end
    end
    sticker_config_rx u_sticker_config_rx(.clk(I_clk),.rst_n(I_rst_n),.tick(I_video_user),
        .payload(I_sticker_payload),.request(I_sticker_request),.ack(O_sticker_ack),
        .config_bus(sticker_config));
    wire sticker_ui_overlay;wire [23:0] sticker_ui_pixel;
    reg sticker_ui_q;reg [23:0] sticker_pixel_q;
    sticker_osd u_sticker_osd(.config_bus(sticker_config),.x(S_frog_x),.y(S_frog_y),
        .overlay(sticker_ui_overlay),.pixel(sticker_ui_pixel));
    always @(posedge I_clk or negedge I_rst_n) begin
        if(!I_rst_n) begin sticker_ui_q<=0;sticker_pixel_q<=0;end
        else begin
            sticker_ui_q<=S_video_de_2d && DEBUG_MODE==0 && !S_photo_status_sync[1] &&
                          sticker_config[130:128]!=0 && sticker_ui_overlay;
            sticker_pixel_q<=sticker_ui_pixel;
        end
    end
    assign S_blue_state=0;assign S_blue_selection=0;assign S_blue_size=0;
    assign S_blue_progress=0;assign S_blue_visible=0;
    assign S_blue_anchor_x=0;assign S_blue_anchor_y=0;
    // Bundled-data mailbox: data settles before the request is accepted.
    // Commit only at SOF so menu geometry cannot tear within an HDMI frame.
    (* ASYNC_REG="TRUE" *) reg [2:0] roi_req_sync;
    reg roi_ack;
    reg [72:0] roi_meta,roi_sync,roi_pending,roi_frame;
    assign O_roi_ack=roi_ack;
    always @(posedge I_clk or negedge I_rst_n)begin
      if(!I_rst_n)begin roi_req_sync<=0;roi_ack<=0;roi_meta<=0;roi_sync<=0;roi_pending<=0;roi_frame<=0;end
      else begin
        roi_req_sync<={roi_req_sync[1:0],I_roi_request};roi_meta<=I_roi_payload[72:0];roi_sync<=roi_meta;
        if(roi_req_sync[2]!=roi_ack)begin roi_pending<=roi_sync;roi_ack<=roi_req_sync[2];end
        if(I_video_user)roi_frame<=roi_pending;
      end
    end
    reg [6:0] roi_gain;
    always @(posedge I_clk or negedge I_rst_n)begin
      if(!I_rst_n)roi_gain<=90;
      else if(I_video_user && S_gain_sync==S_gain_settled)roi_gain<=S_gain_settled;
    end
    green_roi_osd #(.PHOTO_ENABLE(1),.IMG_WIDTH(IMG_WIDTH),.PIPELINED(1)) u_roi_osd(
      .clk(I_clk),.rst_n(I_rst_n),
      .photo_state(S_photo_state),.photo_progress(S_photo_progress),.photo_seconds(S_photo_seconds),.snapshot_view(S_photo_status_sync[1]),.auth_status(S_auth_status),
      .x(S_frog_x),.y(S_frog_y),.state(roi_frame[61:58]),.notice(roi_frame[57:54]),
      .preview(roi_frame[53:50]),.mode(roi_frame[72:69]),.selected(roi_frame[49]),.used(roi_frame[48]),
      .speed_valid(S_speed_frame[16] && !S_photo_status_sync[1]),.speed_bcd(S_speed_frame[15:0]),
      .progress(roi_frame[68:62]),.gain(roi_gain),.history(30'd0),.latency_bcd(S_latency_bcd),.latency_valid(S_latency_show),
      .menu_x(roi_frame[47:36]),.menu_y(roi_frame[35:24]),.op_x(roi_frame[23:12]),.op_y(roi_frame[11:0]),
      .lamp_valid(1'b0),.lamp_variant(1'b0),.lamp_color(3'd0),.left(12'd0),.right(12'd0),.top(12'd0),.bottom(12'd0),
      .overlay(roi_overlay),.pixel(roi_pixel));
    wire photo_menu_active=S_photo_state!=0 || S_photo_status_sync[1];
    assign S_menu_overlay=roi_overlay;
    assign S_menu_pixel=roi_pixel;
    // Detector results stay stable between camera frames. Synchronize the bus,
    // and only sample a settled value at the HDMI frame boundary.
    reg [56:0] S_det_meta,S_det_sync,S_det_settled;
    always @(posedge I_clk or negedge I_rst_n) begin
        if(!I_rst_n) begin
            S_det_meta<=0;S_det_sync<=0;S_det_settled<=0;

            S_gain_meta<=90;S_gain_sync<=90;S_gain_settled<=90;
            S_gain_hundreds<=0;S_gain_tens<=9;S_gain_ones<=0;
        end
        else begin
            S_det_meta<={I_auth_status,I_auth_event,I_auth_valid,I_auth_variant,I_detect_valid,I_detect_color,I_detect_left,I_detect_right,I_detect_top,I_detect_bottom};
            S_det_sync<=S_det_meta;S_det_settled<=S_det_sync;

            S_gain_meta<=I_pen_gain;
            S_gain_sync<=S_gain_meta;
            S_gain_settled<=S_gain_sync;

            if(I_video_user && S_gain_sync==S_gain_settled) begin
                S_gain_hundreds<=S_gain_settled>=100 ? 1:0;
                S_gain_tens<=S_gain_tens_calc;
                S_gain_ones<=S_gain_below_100-S_gain_tens_x10;
            end
        end
    end

    // Display encoding: y = round(255 * (x/255)^0.65).
    // Lift shadows without wrapping or changing black/white endpoints.
    // This cannot recover sensor/AWB clipping. Set GAMMA_ENABLE=0 to bypass.
    function [7:0] gamma_lut;
        input [7:0] x;
        begin
            case (x)
                8'd0: gamma_lut = 8'd0;
                8'd1: gamma_lut = 8'd7;
                8'd2: gamma_lut = 8'd11;
                8'd3: gamma_lut = 8'd14;
                8'd4: gamma_lut = 8'd17;
                8'd5: gamma_lut = 8'd20;
                8'd6: gamma_lut = 8'd22;
                8'd7: gamma_lut = 8'd25;
                8'd8: gamma_lut = 8'd27;
                8'd9: gamma_lut = 8'd29;
                8'd10: gamma_lut = 8'd31;
                8'd11: gamma_lut = 8'd33;
                8'd12: gamma_lut = 8'd35;
                8'd13: gamma_lut = 8'd37;
                8'd14: gamma_lut = 8'd39;
                8'd15: gamma_lut = 8'd40;
                8'd16: gamma_lut = 8'd42;
                8'd17: gamma_lut = 8'd44;
                8'd18: gamma_lut = 8'd46;
                8'd19: gamma_lut = 8'd47;
                8'd20: gamma_lut = 8'd49;
                8'd21: gamma_lut = 8'd50;
                8'd22: gamma_lut = 8'd52;
                8'd23: gamma_lut = 8'd53;
                8'd24: gamma_lut = 8'd55;
                8'd25: gamma_lut = 8'd56;
                8'd26: gamma_lut = 8'd58;
                8'd27: gamma_lut = 8'd59;
                8'd28: gamma_lut = 8'd61;
                8'd29: gamma_lut = 8'd62;
                8'd30: gamma_lut = 8'd63;
                8'd31: gamma_lut = 8'd65;
                8'd32: gamma_lut = 8'd66;
                8'd33: gamma_lut = 8'd68;
                8'd34: gamma_lut = 8'd69;
                8'd35: gamma_lut = 8'd70;
                8'd36: gamma_lut = 8'd71;
                8'd37: gamma_lut = 8'd73;
                8'd38: gamma_lut = 8'd74;
                8'd39: gamma_lut = 8'd75;
                8'd40: gamma_lut = 8'd76;
                8'd41: gamma_lut = 8'd78;
                8'd42: gamma_lut = 8'd79;
                8'd43: gamma_lut = 8'd80;
                8'd44: gamma_lut = 8'd81;
                8'd45: gamma_lut = 8'd83;
                8'd46: gamma_lut = 8'd84;
                8'd47: gamma_lut = 8'd85;
                8'd48: gamma_lut = 8'd86;
                8'd49: gamma_lut = 8'd87;
                8'd50: gamma_lut = 8'd88;
                8'd51: gamma_lut = 8'd90;
                8'd52: gamma_lut = 8'd91;
                8'd53: gamma_lut = 8'd92;
                8'd54: gamma_lut = 8'd93;
                8'd55: gamma_lut = 8'd94;
                8'd56: gamma_lut = 8'd95;
                8'd57: gamma_lut = 8'd96;
                8'd58: gamma_lut = 8'd97;
                8'd59: gamma_lut = 8'd98;
                8'd60: gamma_lut = 8'd100;
                8'd61: gamma_lut = 8'd101;
                8'd62: gamma_lut = 8'd102;
                8'd63: gamma_lut = 8'd103;
                8'd64: gamma_lut = 8'd104;
                8'd65: gamma_lut = 8'd105;
                8'd66: gamma_lut = 8'd106;
                8'd67: gamma_lut = 8'd107;
                8'd68: gamma_lut = 8'd108;
                8'd69: gamma_lut = 8'd109;
                8'd70: gamma_lut = 8'd110;
                8'd71: gamma_lut = 8'd111;
                8'd72: gamma_lut = 8'd112;
                8'd73: gamma_lut = 8'd113;
                8'd74: gamma_lut = 8'd114;
                8'd75: gamma_lut = 8'd115;
                8'd76: gamma_lut = 8'd116;
                8'd77: gamma_lut = 8'd117;
                8'd78: gamma_lut = 8'd118;
                8'd79: gamma_lut = 8'd119;
                8'd80: gamma_lut = 8'd120;
                8'd81: gamma_lut = 8'd121;
                8'd82: gamma_lut = 8'd122;
                8'd83: gamma_lut = 8'd123;
                8'd84: gamma_lut = 8'd124;
                8'd85: gamma_lut = 8'd125;
                8'd86: gamma_lut = 8'd126;
                8'd87: gamma_lut = 8'd127;
                8'd88: gamma_lut = 8'd128;
                8'd89: gamma_lut = 8'd129;
                8'd90: gamma_lut = 8'd130;
                8'd91: gamma_lut = 8'd131;
                8'd92: gamma_lut = 8'd131;
                8'd93: gamma_lut = 8'd132;
                8'd94: gamma_lut = 8'd133;
                8'd95: gamma_lut = 8'd134;
                8'd96: gamma_lut = 8'd135;
                8'd97: gamma_lut = 8'd136;
                8'd98: gamma_lut = 8'd137;
                8'd99: gamma_lut = 8'd138;
                8'd100: gamma_lut = 8'd139;
                8'd101: gamma_lut = 8'd140;
                8'd102: gamma_lut = 8'd141;
                8'd103: gamma_lut = 8'd141;
                8'd104: gamma_lut = 8'd142;
                8'd105: gamma_lut = 8'd143;
                8'd106: gamma_lut = 8'd144;
                8'd107: gamma_lut = 8'd145;
                8'd108: gamma_lut = 8'd146;
                8'd109: gamma_lut = 8'd147;
                8'd110: gamma_lut = 8'd148;
                8'd111: gamma_lut = 8'd149;
                8'd112: gamma_lut = 8'd149;
                8'd113: gamma_lut = 8'd150;
                8'd114: gamma_lut = 8'd151;
                8'd115: gamma_lut = 8'd152;
                8'd116: gamma_lut = 8'd153;
                8'd117: gamma_lut = 8'd154;
                8'd118: gamma_lut = 8'd155;
                8'd119: gamma_lut = 8'd155;
                8'd120: gamma_lut = 8'd156;
                8'd121: gamma_lut = 8'd157;
                8'd122: gamma_lut = 8'd158;
                8'd123: gamma_lut = 8'd159;
                8'd124: gamma_lut = 8'd160;
                8'd125: gamma_lut = 8'd160;
                8'd126: gamma_lut = 8'd161;
                8'd127: gamma_lut = 8'd162;
                8'd128: gamma_lut = 8'd163;
                8'd129: gamma_lut = 8'd164;
                8'd130: gamma_lut = 8'd165;
                8'd131: gamma_lut = 8'd165;
                8'd132: gamma_lut = 8'd166;
                8'd133: gamma_lut = 8'd167;
                8'd134: gamma_lut = 8'd168;
                8'd135: gamma_lut = 8'd169;
                8'd136: gamma_lut = 8'd169;
                8'd137: gamma_lut = 8'd170;
                8'd138: gamma_lut = 8'd171;
                8'd139: gamma_lut = 8'd172;
                8'd140: gamma_lut = 8'd173;
                8'd141: gamma_lut = 8'd173;
                8'd142: gamma_lut = 8'd174;
                8'd143: gamma_lut = 8'd175;
                8'd144: gamma_lut = 8'd176;
                8'd145: gamma_lut = 8'd177;
                8'd146: gamma_lut = 8'd177;
                8'd147: gamma_lut = 8'd178;
                8'd148: gamma_lut = 8'd179;
                8'd149: gamma_lut = 8'd180;
                8'd150: gamma_lut = 8'd181;
                8'd151: gamma_lut = 8'd181;
                8'd152: gamma_lut = 8'd182;
                8'd153: gamma_lut = 8'd183;
                8'd154: gamma_lut = 8'd184;
                8'd155: gamma_lut = 8'd185;
                8'd156: gamma_lut = 8'd185;
                8'd157: gamma_lut = 8'd186;
                8'd158: gamma_lut = 8'd187;
                8'd159: gamma_lut = 8'd188;
                8'd160: gamma_lut = 8'd188;
                8'd161: gamma_lut = 8'd189;
                8'd162: gamma_lut = 8'd190;
                8'd163: gamma_lut = 8'd191;
                8'd164: gamma_lut = 8'd191;
                8'd165: gamma_lut = 8'd192;
                8'd166: gamma_lut = 8'd193;
                8'd167: gamma_lut = 8'd194;
                8'd168: gamma_lut = 8'd194;
                8'd169: gamma_lut = 8'd195;
                8'd170: gamma_lut = 8'd196;
                8'd171: gamma_lut = 8'd197;
                8'd172: gamma_lut = 8'd197;
                8'd173: gamma_lut = 8'd198;
                8'd174: gamma_lut = 8'd199;
                8'd175: gamma_lut = 8'd200;
                8'd176: gamma_lut = 8'd200;
                8'd177: gamma_lut = 8'd201;
                8'd178: gamma_lut = 8'd202;
                8'd179: gamma_lut = 8'd203;
                8'd180: gamma_lut = 8'd203;
                8'd181: gamma_lut = 8'd204;
                8'd182: gamma_lut = 8'd205;
                8'd183: gamma_lut = 8'd206;
                8'd184: gamma_lut = 8'd206;
                8'd185: gamma_lut = 8'd207;
                8'd186: gamma_lut = 8'd208;
                8'd187: gamma_lut = 8'd208;
                8'd188: gamma_lut = 8'd209;
                8'd189: gamma_lut = 8'd210;
                8'd190: gamma_lut = 8'd211;
                8'd191: gamma_lut = 8'd211;
                8'd192: gamma_lut = 8'd212;
                8'd193: gamma_lut = 8'd213;
                8'd194: gamma_lut = 8'd213;
                8'd195: gamma_lut = 8'd214;
                8'd196: gamma_lut = 8'd215;
                8'd197: gamma_lut = 8'd216;
                8'd198: gamma_lut = 8'd216;
                8'd199: gamma_lut = 8'd217;
                8'd200: gamma_lut = 8'd218;
                8'd201: gamma_lut = 8'd218;
                8'd202: gamma_lut = 8'd219;
                8'd203: gamma_lut = 8'd220;
                8'd204: gamma_lut = 8'd221;
                8'd205: gamma_lut = 8'd221;
                8'd206: gamma_lut = 8'd222;
                8'd207: gamma_lut = 8'd223;
                8'd208: gamma_lut = 8'd223;
                8'd209: gamma_lut = 8'd224;
                8'd210: gamma_lut = 8'd225;
                8'd211: gamma_lut = 8'd225;
                8'd212: gamma_lut = 8'd226;
                8'd213: gamma_lut = 8'd227;
                8'd214: gamma_lut = 8'd228;
                8'd215: gamma_lut = 8'd228;
                8'd216: gamma_lut = 8'd229;
                8'd217: gamma_lut = 8'd230;
                8'd218: gamma_lut = 8'd230;
                8'd219: gamma_lut = 8'd231;
                8'd220: gamma_lut = 8'd232;
                8'd221: gamma_lut = 8'd232;
                8'd222: gamma_lut = 8'd233;
                8'd223: gamma_lut = 8'd234;
                8'd224: gamma_lut = 8'd234;
                8'd225: gamma_lut = 8'd235;
                8'd226: gamma_lut = 8'd236;
                8'd227: gamma_lut = 8'd236;
                8'd228: gamma_lut = 8'd237;
                8'd229: gamma_lut = 8'd238;
                8'd230: gamma_lut = 8'd238;
                8'd231: gamma_lut = 8'd239;
                8'd232: gamma_lut = 8'd240;
                8'd233: gamma_lut = 8'd240;
                8'd234: gamma_lut = 8'd241;
                8'd235: gamma_lut = 8'd242;
                8'd236: gamma_lut = 8'd242;
                8'd237: gamma_lut = 8'd243;
                8'd238: gamma_lut = 8'd244;
                8'd239: gamma_lut = 8'd244;
                8'd240: gamma_lut = 8'd245;
                8'd241: gamma_lut = 8'd246;
                8'd242: gamma_lut = 8'd246;
                8'd243: gamma_lut = 8'd247;
                8'd244: gamma_lut = 8'd248;
                8'd245: gamma_lut = 8'd248;
                8'd246: gamma_lut = 8'd249;
                8'd247: gamma_lut = 8'd250;
                8'd248: gamma_lut = 8'd250;
                8'd249: gamma_lut = 8'd251;
                8'd250: gamma_lut = 8'd252;
                8'd251: gamma_lut = 8'd252;
                8'd252: gamma_lut = 8'd253;
                8'd253: gamma_lut = 8'd254;
                8'd254: gamma_lut = 8'd254;
                8'd255: gamma_lut = 8'd255;
                default: gamma_lut = 8'd0;
            endcase
        end
    endfunction

    // Synchronous bitmap uses spare ERAM instead of pixel arithmetic/glyph muxes.
    wire S_osd_red_q,S_osd_blue_q;
    reg S_menu_overlay_q;
    anlogic_osd_rom u_anlogic_osd(
        .clk(I_clk),.rst_n(I_rst_n),.de(S_video_de_2d && DEBUG_MODE==0),
        .x(S_x),.y(S_y),.red(S_osd_red_q),.blue(S_osd_blue_q)
    );
    always @(posedge I_clk or negedge I_rst_n) begin
        if(!I_rst_n) S_menu_overlay_q<=0;
        else S_menu_overlay_q<=S_ui_de_q && S_menu_overlay && DEBUG_MODE==0;
    end

    wire [12:0] S_detect_center_x_sum = {1'b0,S_display_left} + {1'b0,S_display_right};
    wire [12:0] S_detect_center_y_sum = {1'b0,S_display_top} + {1'b0,S_display_bottom};
    wire [11:0] S_detect_center_x = S_detect_center_x_sum[12:1];
    wire [11:0] S_detect_center_y = S_detect_center_y_sum[12:1];
    wire S_detect_box_h = S_display_box_valid &&
                          (S_x >= S_display_left) && (S_x <= S_display_right) &&
                          (((S_y >= S_display_top) && (S_y <= S_display_top + 12'd2)) ||
                           ((S_y <= S_display_bottom) && (S_y + 12'd2 >= S_display_bottom)));
    wire S_detect_box_v = S_display_box_valid &&
                          (S_y >= S_display_top) && (S_y <= S_display_bottom) &&
                          (((S_x >= S_display_left) && (S_x <= S_display_left + 12'd2)) ||
                           ((S_x <= S_display_right) && (S_x + 12'd2 >= S_display_right)));
    wire S_detect_cross_h = S_display_box_valid &&
                            (S_x + 12'd8 >= S_detect_center_x) &&
                            (S_x <= S_detect_center_x + 12'd8) &&
                            (S_y + 12'd1 >= S_detect_center_y) &&
                            (S_y <= S_detect_center_y + 12'd1);
    wire S_detect_cross_v = S_display_box_valid &&
                            (S_y + 12'd8 >= S_detect_center_y) &&
                            (S_y <= S_detect_center_y + 12'd8) &&
                            (S_x + 12'd1 >= S_detect_center_x) &&
                            (S_x <= S_detect_center_x + 12'd1);
    wire S_detect_overlay = S_detect_box_h || S_detect_box_v;
    function lamp_label_pixel;
        input [2:0] lamp_color;
        input lamp_variant;
        input [6:0] dx;
        input [3:0] dy;
        reg [55:0] letters;
        reg [7:0] ch;
        reg [34:0] bits;
        integer index;
        integer column;
        integer row;
        begin
            case(lamp_color)
                2: letters=lamp_variant ? "GREEN1 ":"GREEN  ";
                3: letters=lamp_variant ? "BLUE1  ":"BLUE   ";
                4: letters=lamp_variant ? "YELLOW1":"YELLOW ";
                5: letters=lamp_variant ? "PURPLE1":"PURPLE ";
                default: letters="UNKNOWN";
            endcase
            index=dx/12; column=(dx%12)/2; row=dy/2;
            ch=8'd32; bits=0;
            if(index<7) ch=letters >> ((6-index)*8);
            case(ch)
                8'd82: bits=35'b11110_10001_10001_11110_10100_10010_10001;
                8'd69: bits=35'b11111_10000_10000_11110_10000_10000_11111;
                8'd68: bits=35'b11110_10001_10001_10001_10001_10001_11110;
                8'd71: bits=35'b01110_10001_10000_10111_10001_10001_01110;
                8'd78: bits=35'b10001_11001_11001_10101_10011_10011_10001;
                8'd66: bits=35'b11110_10001_10001_11110_10001_10001_11110;
                8'd76: bits=35'b10000_10000_10000_10000_10000_10000_11111;
                8'd85: bits=35'b10001_10001_10001_10001_10001_10001_01110;
                8'd75: bits=35'b10001_10010_10100_11000_10100_10010_10001;
                8'd79: bits=35'b01110_10001_10001_10001_10001_10001_01110;
                8'd87: bits=35'b10001_10001_10001_10101_10101_10101_01010;
                8'd89: bits=35'b10001_10001_01010_00100_00100_00100_00100;
                8'd80: bits=35'b11110_10001_10001_11110_10000_10000_10000;
                8'd49: bits=35'b00100_01100_00100_00100_00100_00100_01110;
                default: bits=0;
            endcase
            lamp_label_pixel=0;
            if(column<5 && row<7 && index<7)
                lamp_label_pixel=bits[34-row*5-column];
        end
    endfunction
    wire [11:0] S_label_x = S_display_variant && S_display_color!=2 ?
        (S_display_right<12'd1188 ? S_display_right+12'd8 :
         S_display_left>12'd92 ? S_display_left-12'd92:12'd0):S_display_left;
    wire [11:0] S_label_y = S_display_variant && S_display_color!=2 ? S_display_top :
        (S_display_bottom < 12'd698 ? S_display_bottom + 12'd4 : S_display_top - 12'd18);
    wire [11:0] S_label_dx = S_x - S_label_x;
    wire [11:0] S_label_dy = S_y - S_label_y;
    wire S_lamp_label = S_display_box_valid && S_label_dx < 12'd84 &&
                        S_label_dy < 12'd14 &&
                        lamp_label_pixel(S_display_color,S_display_variant,S_label_dx[6:0],S_label_dy[3:0]);


    assign O_video_rd_en = I_video_de;

    // Latch the camera-domain result only at an HDMI frame boundary so the
    // multi-bit coordinates remain coherent for the entire displayed frame.
    always @(posedge I_clk or negedge I_rst_n) begin
        if(!I_rst_n) begin
            S_auth_valid<=0;S_auth_event<=0;S_auth_variant<=0;S_auth_status<=0;
            S_detect_valid <= 1'b0;
            S_detect_color <= 2'd0;
            S_detect_left <= 12'd0;
            S_detect_right <= 12'd0;
            S_detect_top <= 12'd0;
            S_detect_bottom <= 12'd0;
            S_display_box_valid<=0;S_display_color<=0;S_display_variant<=0;
            S_display_left<=0;S_display_right<=0;
            S_display_top<=0;S_display_bottom<=0;
        end else if(I_video_user) begin
            if(S_det_sync==S_det_settled) begin
                {S_auth_status,S_auth_event,S_auth_valid,S_auth_variant,S_detect_valid,S_detect_color,S_detect_left,S_detect_right,S_detect_top,S_detect_bottom}
                    <=S_det_settled;
                if(!S_det_settled[53])
                    S_display_box_valid<=0;
                else if(S_det_settled[51] &&
                        (!S_display_box_valid ||
                         S_det_settled[50:48]==S_display_color)) begin
                    S_display_box_valid<=1;
                    S_display_color<=S_det_settled[50:48];
                    S_display_variant<=S_det_settled[52];
                    S_display_left<=S_det_settled[47:36];
                    S_display_right<=S_det_settled[35:24];
                    S_display_top<=S_det_settled[23:12];
                    S_display_bottom<=S_det_settled[11:0];
                end
            end
            else begin S_detect_valid<=0;S_auth_valid<=0;end
        end
    end

    always @(posedge I_clk or negedge I_rst_n) begin
        if(!I_rst_n) begin
            S_frog_user_pipe<=0;S_frog_last_pipe<=0;S_frog_scan_x<=0;S_frog_scan_y<=0;
        end else begin
            S_frog_user_pipe<={S_frog_user_pipe[0],I_video_user};
            S_frog_last_pipe<={S_frog_last_pipe[0],I_video_last};
            // Register frame-origin correction one stage earlier. The OSD sees
            // identical coordinates without a frame-start mux on every pixel path.
            if(S_frog_user_pipe[0]) begin
                S_frog_scan_x<=0;S_frog_scan_y<=0;
            end else if(S_frog_user_pipe[1]) begin
                S_frog_scan_x<=S_video_de_2d ? 12'd1:12'd0;S_frog_scan_y<=0;
            end else if(S_video_de_2d) begin
                if(S_frog_last_pipe[1]) begin S_frog_scan_x<=0;S_frog_scan_y<=S_frog_scan_y+1'b1;end
                else S_frog_scan_x<=S_frog_scan_x+1'b1;
            end
        end
    end
    sticker_renderer u_sticker_renderer(
        .clk(I_clk),.rst_n(I_rst_n),.tick(I_video_user),.config_bus(render_config),
        .scan_x(S_frog_x),.scan_y(S_frog_y),
        .scan_de(S_video_de_2d && DEBUG_MODE==0),
        .alpha(S_frog_alpha),.pixel(S_frog_pixel));
    always @(posedge I_clk or negedge I_rst_n) begin
        if(!I_rst_n) begin
            S_x <= 12'd0;
            S_y <= 12'd0;
        end
        else if(I_video_user) begin
            S_x <= 12'd0;
            S_y <= 12'd0;
        end
        else if(I_video_de) begin
            if(I_video_last) begin
                S_x <= 12'd0;
                S_y <= S_y + 12'd1;
            end
            else begin
                S_x <= S_x + 12'd1;
            end
        end
    end

    always @(posedge I_clk or negedge I_rst_n) begin
        if(!I_rst_n) begin
            S_video_vsync_1d <= 1'b0;
            S_video_vsync_2d <= 1'b0;
            S_video_hsync_1d <= 1'b0;
            S_video_hsync_2d <= 1'b0;
            S_video_de_1d    <= 1'b0;
            S_video_de_2d    <= 1'b0;
            S_prebase_vsync     <= 1'b0;
            S_prebase_hsync     <= 1'b0;
            S_prebase_de        <= 1'b0;
            S_base_no_ui      <= 24'd0;
        end
        else begin
            S_video_vsync_1d <= I_video_vsync;
            S_video_vsync_2d <= S_video_vsync_1d;
            S_prebase_vsync     <= S_video_vsync_2d;

            S_video_hsync_1d <= I_video_hsync;
            S_video_hsync_2d <= S_video_hsync_1d;
            S_prebase_hsync     <= S_video_hsync_2d;

            S_video_de_1d    <= I_video_de;
            S_video_de_2d    <= S_video_de_1d;
            S_prebase_de        <= S_video_de_2d;
            S_video_data_1d  <= I_video_rd_data;
            // Reuse the existing second data stage: no added video latency.
            if(DEBUG_MODE == 1) begin
                if(S_video_de_2d) begin
                    if(S_x < 12'd128)
                        S_base_no_ui <= 24'hff0000;
                    else if(S_x < 12'd256)
                        S_base_no_ui <= 24'h00ff00;
                    else if(S_x < 12'd384)
                        S_base_no_ui <= 24'h0000ff;
                    else if(S_x < 12'd512)
                        S_base_no_ui <= 24'hffff00;
                    else if(S_x < 12'd640)
                        S_base_no_ui <= 24'h00ffff;
                    else if(S_x < 12'd768)
                        S_base_no_ui <= 24'hff00ff;
                    else if(S_x < 12'd896)
                        S_base_no_ui <= 24'hffffff;
                    else
                        S_base_no_ui <= 24'h202020;
                end
                else begin
                    S_base_no_ui <= 24'd0;
                end
            end
            else if(DEBUG_MODE == 2) begin
                if(S_video_de_2d) begin
                    case (I_debug_status)
                        4'b0000: S_base_no_ui <= 24'h000000;
                        4'b0001: S_base_no_ui <= 24'hff0000;
                        4'b0011: S_base_no_ui <= 24'hffff00;
                        4'b0111: S_base_no_ui <= 24'h00ff00;
                        4'b1111: S_base_no_ui <= I_video_rd_data;
                        default: S_base_no_ui <= 24'h0000ff;
                    endcase
                end
                else begin
                    S_base_no_ui <= 24'd0;
                end
            end
            else if(DEBUG_MODE == 3) begin
                if(S_video_de_2d) begin
                    if(S_x < (IMG_WIDTH/4))
                        S_base_no_ui <= I_debug_status[0] ? 24'hff8000 : 24'h404040;
                    else if(S_x < (IMG_WIDTH/2))
                        S_base_no_ui <= I_debug_status[1] ? 24'hffff00 : 24'h404040;
                    else if(S_x < ((IMG_WIDTH*3)/4))
                        S_base_no_ui <= I_debug_status[2] ? 24'hff0000 : 24'h404040;
                    else
                        S_base_no_ui <= I_debug_status[3] ? 24'h00ffff : 24'h404040;
                end
                else begin
                    S_base_no_ui <= 24'd0;
                end
            end
            else begin
                if(S_video_de_2d && S_display_box_valid && !S_photo_status_sync[1] && (S_detect_overlay || S_lamp_label))
                    S_base_no_ui <= S_display_color == 2'd2 ? 24'h00ff40 :
                                   S_display_color == 3'd3 ? 24'h3090ff :
                                   S_display_color == 3'd4 ? 24'hffff30 :
                                   S_display_color == 3'd5 ? 24'hd050ff : 24'h909090;
                else
                    S_base_no_ui <= S_video_data_2d;
            end
        end
    end

    always @(posedge I_clk or negedge I_rst_n) begin
      if(!I_rst_n)begin
        S_base_data<=0;S_base_vsync<=0;S_base_hsync<=0;S_base_de<=0;S_ui_de_q<=0;
        S_osd_red_delay<=0;S_osd_blue_delay<=0;S_sticker_ui_delay<=0;
        S_sticker_pixel_delay<=0;S_frog_alpha_delay<=0;S_frog_pixel_delay<=0;
      end else begin
        S_ui_de_q<=S_video_de_2d;
        S_base_data<=(DEBUG_MODE==0 && S_ui_de_q && S_menu_overlay)?S_menu_pixel:S_base_no_ui;
        S_base_vsync<=S_prebase_vsync;S_base_hsync<=S_prebase_hsync;S_base_de<=S_prebase_de;
        S_osd_red_delay<=S_osd_red_q;S_osd_blue_delay<=S_osd_blue_q;
        S_sticker_ui_delay<=sticker_ui_q;S_sticker_pixel_delay<=sticker_pixel_q;
        S_frog_alpha_delay<=S_frog_alpha;S_frog_pixel_delay<=S_frog_pixel;
      end
    end
    always @(posedge I_clk or negedge I_rst_n) begin
        if(!I_rst_n) begin
            O_hdmi_vsync<=0;O_hdmi_hsync<=0;O_hdmi_de<=0;O_hdmi_data<=0;
        end else begin
            O_hdmi_vsync<=S_base_vsync;O_hdmi_hsync<=S_base_hsync;O_hdmi_de<=S_base_de;
            O_hdmi_data<=(shutter_pipe[3] && DEBUG_MODE==0) ? 24'd0:S_sticker_ui_delay ? S_sticker_pixel_delay:S_menu_overlay_q ? S_base_data:
                         S_osd_red_delay ? 24'hed1c24:S_osd_blue_delay ? 24'h172b4d:
                         S_frog_alpha_delay ? S_frog_pixel_delay:S_base_data;
        end
    end

endmodule

// This controller ticks at the existing ~60 Hz HDMI frame rate.


module green_pen_menu #(parameter IMG_WIDTH=1280)(
 input [11:0] x,y,anchor_x,anchor_y,
 input [3:0] mode, input [1:0] state,
 input [6:0] progress, input green,
 input [6:0] move_distance,
 input [2:0] photo_state,input [6:0] photo_progress,input [1:0] photo_seconds,
 input [1:0] photo_selection,input snapshot_view,input [1:0] photo_result,
 input [1:0] auth_status,
 input [29:0] frame_history,
 input [3:0] gain_hundreds,gain_tens,gain_ones,
 input [2:0] blue_state,input [1:0] blue_selection,blue_size,
 input [6:0] blue_progress,input blue_visible,
 input [11:0] blue_anchor_x,blue_anchor_y,
 output overlay, output [23:0] pixel
);
 wire blue_menu_active=blue_state!=0;
 wire expanded=(state!=0)||(progress!=0)||(photo_state!=0)||snapshot_view||
               (auth_status==1)||blue_menu_active;
 // The upper panel is reserved for the 30-frame diagnostic history.
 wire [11:0] hx=x-(IMG_WIDTH-272),hy=y-12'd18;
 wire history_panel=hx<264 && hy<112;
 wire [11:0] htx=hx-12'd8,hty=hy-12'd8;
 wire [3:0] history_index=htx[7:4];
 wire [1:0] history_line=hty[6:5];
 // The original pen menu is kept intact immediately below it.
 wire [11:0] dx=x-(IMG_WIDTH-272),dy=y-12'd142;
 wire [8:0] panel_height=expanded ? 9'd160:9'd64;
 wire panel=dx<264 && dy<panel_height;
 wire [11:0] tx=dx-12'd8,ty=dy-12'd8;
 wire [1:0] line_index=ty[6:5];
 reg [127:0] text_line;
 function [127:0] filter_name;
 input [3:0] m;
 begin case(m)
 4'd0:filter_name="1/7 NORMAL      ";
 4'd4:filter_name="2/7 COOL        ";
 4'd5:filter_name="3/7 WARM        ";
 4'd8:filter_name="4/7 VINTAGE     ";
 4'd13:filter_name="5/7 ENHANCE     ";
 4'd1:filter_name="6/7 BW EDGE     ";
 4'd2:filter_name="7/7 CARTOON     ";
 4'd3:filter_name="NORMAL          ";
 4'd6:filter_name="COOL            ";
 4'd7:filter_name="WARM            ";
 4'd10:filter_name="VINTAGE         ";
 4'd12,4'd14:filter_name="NORMAL          ";
 4'd15:filter_name="ENHANCE         ";
 default:filter_name="NORMAL          ";
 endcase end endfunction
 function [127:0] blue_mode_name;
 input [1:0] m;
 begin case(m)
  0:blue_mode_name="1/3 SIZE        ";
  1:blue_mode_name="2/3 POSITION    ";
  default:blue_mode_name="3/3 HIDE        ";
 endcase end endfunction
 function [127:0] blue_size_name;
 input [1:0] s;
 begin case(s)
  0:blue_size_name="1/4 SMALL 64X96 ";
  1:blue_size_name="2/4 96X144      ";
  2:blue_size_name="3/4 128X192     ";
  default:blue_size_name="4/4 LARGE160X240";
 endcase end endfunction
 always @* begin
 text_line="                ";
 case(line_index)
 0:text_line=state==2 ? "APPLIED         ":state==1 ? "GREEN PEN MENU  ":"FILTER          ";
 1:text_line=filter_name(mode);
 2:text_line=state==2 ? "REMOVE GREEN PEN":state==1 ? "LR FILTER UDGAIN":"HOLD TO OPEN    ";
 3:text_line=state==1 ? "HOLD TO APPLY   ":"GREEN PEN ONLY  ";
 endcase
 if(auth_status!=2 && state==0 && photo_state==0 && !snapshot_view) begin
 case(line_index)
 0:text_line=auth_status==1 ? "CHECKING CODE   ":"                ";
 1:text_line=filter_name(mode);
 2:text_line="KEEP PEN STILL  ";
 3:text_line="KEEP PEN STILL  ";
 endcase
 end
 if(blue_menu_active && photo_state==0 && !snapshot_view) begin
 case(line_index)
 0:text_line=blue_state==1 ? "BLUE DIRECT CTRL":
             blue_state==2 ? "MOVE CHARACTER  ":"CHARACTER SAVED ";
 1:text_line=blue_state==1 ? blue_size_name(blue_size):
             blue_state==2 ? "FOLLOW BLUE PEN ":
             blue_visible ? "VISIBLE         ":"HIDDEN          ";
 2:text_line=blue_state==1 ? "L- R+ UP MOVE   ":
             blue_state==2 ? "HOLD STILL     ":"REMOVE BLUE PEN ";
 3:text_line=blue_state==1 ?
             (blue_visible ? "DN HIDE C SAVE  ":"DN SHOW C SAVE  "):
             blue_state==2 ? "SAVE IN 1 SEC   ":"                ";
 endcase
 end
 if(photo_state!=0 || snapshot_view) begin
 case(line_index)
 0:text_line=(photo_state==6 || photo_state==7 || snapshot_view) ? "YELLOW1 ALBUM   ":"YELLOW PHOTO    ";
 1:case(photo_state)
    2:case(photo_seconds)
      3:text_line="CAPTURE IN 3    ";
      2:text_line="CAPTURE IN 2    ";
      1:text_line="CAPTURE IN 1    ";
      default:text_line="CAPTURING       ";
      endcase
    3:text_line="CAPTURED        ";
    6:text_line=snapshot_view ? "PHOTO DISPLAY   ":"OPENING PHOTO   ";
    7:text_line="NO PHOTO        ";
    4:text_line="CANCELLED       ";
    default:text_line=snapshot_view ? "PHOTO DISPLAY   ":"LIVE VIDEO      ";
   endcase
 2:text_line=photo_state==2 ? "REMOVE PEN NOW  ":
             photo_state==6 ? "PEN OFF TO LIVE ":
             photo_state==7 ? "USE YELLOW FIRST":
             snapshot_view ? "KEY4 FOR LIVE   ":"YELLOW CAPTURE  ";
 3:text_line=photo_state==2 ? "AUTO CAPTURE    ":"YEL1 SHOW PHOTO ";
 endcase
 end
 end
 wire [7:0] character=text_line[127-tx[7:4]*8 -:8];
