 8'd90:glyph=35'b11111000010001000100010001000011111;
 8'd49:glyph=35'b00100011000010000100001000010001110;
  8'd48:glyph=35'b01110100011001110101110011000101110;
 8'd50:glyph=35'b01110100010000100010001000100011111;
 8'd51:glyph=35'b11110000010000101110000010000111110;
 8'd52:glyph=35'b00010001100101010010111110001000010;
 8'd53:glyph=35'b11111100001000011110000010000111110;
 8'd54:glyph=35'b01110100001000011110100011000101110;
 8'd55:glyph=35'b11111000010001000100010000100001000;
 8'd56:glyph=35'b01110100011000101110100011000101110;
 8'd57:glyph=35'b01110100011000101111000010000101110;
 8'd47:glyph=35'b00001000100001000100010000100010000;
 8'd43:glyph=35'b00000001000010011111001000010000000;
 default:glyph=0;
 endcase end endfunction
 function [7:0] brightness_char;
 input [3:0] i,h,t,o;
 begin case(i)
  0:brightness_char=8'd66;1:brightness_char=8'd82;
  2:brightness_char=8'd73;3:brightness_char=8'd71;
  4:brightness_char=8'd72;5:brightness_char=8'd84;
  6:brightness_char=8'd78;7:brightness_char=8'd69;
  8:brightness_char=8'd83;9:brightness_char=8'd83;
 10:brightness_char=8'd32;11:brightness_char=8'd48+h;
 12:brightness_char=8'd48+t;13:brightness_char=8'd48+o;
 default:brightness_char=8'd32;
 endcase end endfunction
 wire [34:0] bits=glyph(character);
 wire ink=tx<256 && ty<128 && tx[3:1]<5 && ty[4:1]<7 &&
          bits[34-ty[4:1]*5-tx[3:1]];
 wire history_value=history_line[0] ? frame_history[14-history_index]:
                                     frame_history[29-history_index];
 wire [7:0] history_bit_character=history_index<15 ?
                                  (history_value ? 8'd49:8'd48):8'd32;
 wire [7:0] history_character=history_line==2 ?
        brightness_char(history_index,gain_hundreds,gain_tens,gain_ones):
        history_bit_character;
 wire [34:0] history_bits=glyph(history_character);
 wire history_ink=htx<240 && hty<96 && history_index<15 &&
                  htx[3:1]<5 && hty[4:1]<7 &&
                  history_bits[34-hty[4:1]*5-htx[3:1]];
 wire bar=expanded && (auth_status==2 || photo_state!=0 || blue_menu_active) &&
          ((photo_state==1 || photo_state==5) ||
           (photo_state==0 && (state!=2 || blue_menu_active))) &&
          dx>=8 && dx<128 && dy>=144 && dy<150;
 wire [7:0] photo_bar={1'b0,photo_progress}<<1;
 wire [7:0] bar_width=blue_menu_active ? ({1'b0,blue_progress}<<1):
                              photo_state==5 ? (({1'b0,photo_progress}<<1)+({1'b0,photo_progress}>>1)) : photo_state==1 ? photo_bar : state==1 ? ({1'b0,progress}<<1)+({1'b0,progress}>>1) :
                              ({1'b0,progress}<<1);
 wire border=dx==0 || dx==263 || dy==0 || dy==panel_height-1'b1;
 wire history_border=hx==0 || hx==263 || hy==0 || hy==111;
 wire [11:0] green_dx=x>=anchor_x ? x-anchor_x:anchor_x-x;
 wire [11:0] green_dy=y>=anchor_y ? y-anchor_y:anchor_y-y;
 wire green_guides=state==1 && !snapshot_view;
 wire green_center=green_guides && green_dx<=4 && green_dy<=4 &&
                   (green_dx==4 || green_dy==4);
 // The whole 5px ring lies beyond the horizontal activation threshold.
 wire [11:0] target_distance={5'd0,move_distance}+12'd6;
 wire [11:0] ring_x=green_dx>=target_distance ?
                   green_dx-target_distance:target_distance-green_dx;
 wire green_targets=green_guides &&
      ((green_dy==5 && ring_x<=2) || (green_dy==4 && ring_x==3) ||
       (green_dy==3 && ring_x==4) || (green_dy<=2 && ring_x==5));
 // Blue SIZE/menu selection uses the same return-to-centre gesture as green.
 // This is part of the menu overlay and therefore renders above the character.
 wire blue_center=blue_state==1 && !snapshot_view &&
             x+4>=blue_anchor_x && x<=blue_anchor_x+4 &&
             y+4>=blue_anchor_y && y<=blue_anchor_y+4 &&
             (x+4==blue_anchor_x || x==blue_anchor_x+4 ||
              y+4==blue_anchor_y || y==blue_anchor_y+4);
 assign overlay=history_panel || panel || green_center || green_targets || blue_center;
 assign pixel=history_panel ? (history_ink ? 24'hffffff:
                               history_border ? 24'h607080:24'h101820):
              panel ? (ink ? (line_index==1 ? 24'hffff60:24'hffffff):
                      border ? (green ? 24'h40ff80:24'h607080):
                      bar ? (dx-8<bar_width ? 24'h40ff80:24'h405060):24'h101820):
              blue_center ? 24'h3090ff:24'h40ff80;
endmodule

// Authenticate normal yellow to start a single countdown; YELLOW1 opens album.
// Compatibility ports/parameters are retained for existing project interfaces.
module red_pen_capture #(
    parameter HOLD_FRAMES=60, DELAY_FRAMES=180, CLEAR_FRAMES=30,
    parameter TIMEOUT_FRAMES=600, NOTICE_FRAMES=120, APPLY_FRAMES=48, MOVE_FRAMES=3, EXIT_FRAMES=120
)(
    input clk,rst_n,tick,enable,detected,auth_enter,auth_valid,variant,
    input [2:0] color,
    input snapshot_valid,snapshot_view,
    output reg [1:0] result_code,
    output reg view_toggle,view_target,
    output reg [1:0] selection,
    input [11:0] left,right,top,bottom,
    output reg [2:0] state,
    output reg [6:0] progress,
    output [1:0] seconds_left,
    output reg capture_toggle
);
    localparam IDLE=0,COUNTDOWN=2,DONE=3,CANCELLED=4,ALBUM=6,NO_PHOTO=7;
    localparam SECOND_FRAMES=(DELAY_FRAMES+2)/3;
    localparam TIMER_BITS=$clog2((DELAY_FRAMES>NOTICE_FRAMES ? DELAY_FRAMES:NOTICE_FRAMES)+1);
    reg [TIMER_BITS-1:0] elapsed;
    // There is no additional dwell/progress gesture. Only a NEW auth event can
    // start an action, so a continuously illuminated yellow cannot retrigger.
    assign seconds_left=state!=COUNTDOWN ? 2'd0:
                        elapsed<SECOND_FRAMES ? 2'd3:
                        elapsed<SECOND_FRAMES*2 ? 2'd2:2'd1;
    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            state<=IDLE;progress<=0;result_code<=0;view_toggle<=0;
            view_target<=0;selection<=0;elapsed<=0;capture_toggle<=0;
        end else if(tick) begin
            progress<=0;
            if(auth_enter) begin
                elapsed<=0;result_code<=0;
                if(enable && auth_valid && color==4) begin
                    if(variant) begin
                        selection<=1;
                        if(snapshot_valid) begin
                            state<=ALBUM;view_target<=1;
                            if(!snapshot_view) view_toggle<=~view_toggle;
                        end else begin state<=NO_PHOTO;result_code<=3;end
                    end else begin
                        selection<=0;state<=COUNTDOWN;view_target<=0;
                        if(snapshot_view) view_toggle<=~view_toggle;
                    end
                end else begin
                    state<=IDLE;
                    if(state==ALBUM) begin
                        view_target<=0;
                        if(snapshot_view || view_target) view_toggle<=~view_toggle;
                    end
                end
            end else case(state)
                COUNTDOWN: begin
                    // Taking the pen out of shot does not cancel the countdown.
                    if(elapsed>=DELAY_FRAMES-1) begin
                        capture_toggle<=~capture_toggle;state<=DONE;elapsed<=0;
                    end else elapsed<=elapsed+1'b1;
                end
                ALBUM: begin
                    // The upstream grant already tolerates 19 missing camera
                    // frames. Do not count HDMI frames or raw detection gaps.
                    if(!auth_valid) begin
                        state<=IDLE;view_target<=0;elapsed<=0;
                        if(snapshot_view || view_target) view_toggle<=~view_toggle;
                    end
                end
                DONE,NO_PHOTO,CANCELLED: begin
                    if(elapsed>=NOTICE_FRAMES-1) begin state<=IDLE;elapsed<=0;end
                    else elapsed<=elapsed+1'b1;
                end
                default:begin state<=IDLE;elapsed<=0;end
            endcase
        end
    end
endmodule

